 <body><div class="app"><header class="topbar"><div class="brand" data-page="home"><div class="brand-mark">▧</div><div><div class="brand-name">PAPER <span>WORLD</span></div><div class="brand-sub">ULTIMATE V3.0</div></div></div><div class="top-spacer"></div><div id="playerChip" class="player-chip" data-page="profile"><div class="avatar" id="topAvatar">🟧</div><div class="player-meta"><div class="player-name" id="topName">PaperPilot</div><div class="player-level" id="topLevel">LEVEL 1 · 35 / 100 XP</div><div class="xp-track"><div class="xp-fill" id="topXp"></div></div></div></div><div class="coin-pill">● <span id="coinCount">250</span></div><button class="icon-btn" data-page="settings" aria-label="Settings">⚙</button></header><main class="layout"><nav class="nav" id="nav"></nav><div id="view" class="page"></div><div class="footer">PAPER WORLD ULTIMATE V3.0 <span>·</span> OFFLINE ARCADE</div></main><div class="toast" id="toast"></div></div>
 <script>
+const MAPS=[['Classic Arena','The balanced paper playground. A perfect place to start.','#4c5380','🟪',0],['Neon City','Bright lights, tight turns, no room to blink.','#252052','🌃',1],['Desert World','Warm sands and wide-open territory.','#bd8242','🌵',2],['Ice Kingdom','A crisp frozen realm with slippery-looking lanes.','#7fb9d7','❄️',3],['Forest World','Grow your empire beneath the leafy canopy.','#477951','🌲',4],['Space Arena','Claim your corner of the endless cosmos.','#242447','🪐',5],['Candy Land','A sugary map with deliciously bright colors.','#e994bd','🍭',6],['Volcano','A fiery arena where bold plays pay off.','#9e4142','🌋',7],['Cyber World','Glitch through a high-tech neon grid.','#4f45a5','💠',8],['Golden Kingdom','A gilded arena reserved for legends.','#b89537','👑',9]];
+const MODES=[['classic','🏁','Classic','Claim territory and outlast 8 clever rivals.','8 bots · 3 min'],['time','⏱️','Time Attack','Three minutes. Make every trail count.','3:00 · high score'],['survival','🛡️','Survival','Bots get faster and bolder as time goes on.','endless · escalating'],['practice','🌱','Practice','Learn the ropes in a relaxed 2-bot match.','2 easy bots'],['hardcore','🔥','Hardcore','Expert rivals. One arena. No mercy.','8 expert bots']];
+const SKINS=['Classic','Red','Blue','Green','Yellow','Purple','Rainbow','Fire','Ice','Galaxy','Gold','Diamond','Shadow','Neon','Crystal','Lava','Cyber','Ocean','Candy','Royal'];
+const SHOP={Skins:SKINS.map((n,i)=>[n,['🟪','🟥','🟦','🟩','🟨','🟣','🌈','🔥','🧊','🌌','🟡','💎','🌑','💡','🔮','🌋','🤖','🌊','🍬','👑'][i],i<4?0:80+i*35]),Trails:[['Default Trail','〰️',0],['Rainbow Trail','🌈',160],['Fire Trail','🔥',180],['Ice Trail','❄️',180],['Neon Trail','💫',220],['Galaxy Trail','🌌',250],['Lightning Trail','⚡',280],['Golden Trail','✨',320]],'Death Effects':[['Star Explosion','⭐',100],['Color Explosion','🎨',140],['Pixel Explosion','👾',160],['Rainbow Explosion','🌈',200],['Bubble Explosion','🫧',180]],Avatars:[['Paper Pilot','🟧',0],['Happy Cloud','☁️',80],['Cosmic Cat','🐱',130],['Pixel Fox','🦊',160],['Star Bot','🤖',190],['Jelly Friend','🪼',220],['Tiny Crown','👑',260],['Lucky Ghost','👻',300]]};
+const DEFAULT={name:'PaperPilot',level:1,xp:35,coins:250,matches:0,wins:0,losses:0,captured:0,eliminations:0,best:0,skin:'Classic',avatar:'🟧',selectedMap:0,unlockedMaps:[0],owned:{Skins:['Classic','Red','Blue','Green'],'Trails':['Default Trail'],'Death Effects':[],'Avatars':['Paper Pilot']},equipped:{Skins:'Classic','Trails':'Default Trail','Death Effects':'','Avatars':'Paper Pilot'},sound:true,highscore:0,missions:{captures:0,wins:0},dailyDay:'',dailyStreak:0};
+let save;try{save={...DEFAULT,...JSON.parse(localStorage.getItem('paperWorldSave')||'{}')};save.owned={...DEFAULT.owned,...(save.owned||{})};save.equipped={...DEFAULT.equipped,...(save.equipped||{})}}catch{save={...DEFAULT}};function persist(){localStorage.setItem('paperWorldSave',JSON.stringify(save));updateHeader()}
+const NAV=[['home','⌂','HOME'],['maps','▦','MAPS'],['modes','◉','MODES'],['shop','✦','SHOP'],['missions','⚑','MISSIONS'],['rewards','🎁','REWARDS'],['leaderboard','♜','RANKS'],['profile','◉','PROFILE'],['settings','⚙','SETTINGS']];let currentPage='home',shopTab='Skins',selectedMode='classic';
+const $=s=>document.querySelector(s),view=$('#view');function updateHeader(){ $('#topName').textContent=save.name;$('#topAvatar').textContent=save.avatar;$('#topLevel').textContent=`LEVEL ${save.level} · ${save.xp} / 100 XP` $('#topXp').style.width=`${save.xp}%`;$('#coinCount').textContent=save.coins }
+function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
+function navDraw(){ $('#nav').innerHTML=NAV.map(([id,ic,n])=>`<button data-page="${id}" class="${currentPage===id?'active':''}"><span class="nav-icon">${ic}</span>${n}</button>`).join('') }
+function screenHead(title,sub){return `<div class="screen-title"><div><div class="eyebrow">PAPER WORLD / ${title.toUpperCase()}</div><h1>${title}</h1><p>${sub}</p></div><button class="back-btn" data-page="home">← BACK HOME</button></div>`}
+function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR NEXT GREAT RUN STARTS HERE</div><h1>MAKE YOUR<br><em>MARK.</em></h1><p>Color the arena. Draw a daring trail. Close the loop and turn empty space into your kingdom.</p><div class="actions"><button class="primary" data-action="quickplay">PLAY NOW <span class="arrow">↗</span></button><button class="secondary" data-page="maps">CHOOSE A MAP</button><span class="tiny-note">✦ Free to play · Offline ready</span></div></div><div class="showcase"><div class="show-grid"></div><div class="show-tag tag-a">✦ CURRENT SEASON <b>Paper Planes</b></div><div class="territory-board">${Array.from({length:63},(_,i)=>`<i class="tile" style="animation-delay:${(i%9)*-.22}s"></i>`).join('')}</div><div class="paper-player">▧</div><i class="floating-square f1"></i><i class="floating-square f2"></i><i class="floating-square f3"></i><div class="show-tag tag-b"><b>01</b>ONE TRAIL. BIG AMBITION.</div></div></section><div class="section-head"><div><h2>Pick your playstyle</h2><p>Five ways to make the arena yours.</p></div><button class="text-link" data-page="modes">ALL MODES →</button></div><section class="mode-grid">${MODES.slice(0,4).map(([id,ic,n,d,s])=>`<article class="mode-card" data-mode="${id}"><div class="mode-icon">${ic}</div><h3>${n}</h3><p>${d}</p><span class="chev">↗</span></article>`).join('')}</section><section class="bottom-grid"><article class="panel mission-card"><div class="mission-top"><h3>⚑ Daily mission</h3><span>+75 COINS</span></div><div class="mission-desc">Capture 500 tiles across your matches</div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,(save.missions.captures||0)/5)}%"></div></div><div class="mission-foot"><span>${Math.min(500,save.missions.captures||0)} / 500 tiles</span><button class="text-link" data-page="missions">VIEW MISSIONS →</button></div></article><article class="panel daily-card"><div class="mission-top"><h3>🎁 Daily drop</h3><span>READY TO CLAIM?</span></div><div class="mission-desc">A little something to keep your paper empire growing.</div><button class="small-btn secondary" data-page="rewards" style="padding:9px 13px;font-size:9px">OPEN REWARDS →</button></article></section>`}
+function modes(){return `${screenHead('Game modes','Every run is a new chance to own the board.')}<div class="cards">${MODES.map(([id,ic,n,d,s])=>`<article class="panel feature-card"><div style="font-size:23px">${ic}</div><h3>${n}</h3><p>${d}<br><b style="color:#c8f76a">${s}</b></p><button class="primary" data-mode="${id}">START ${n.toUpperCase()} →</button></article>`).join('')}</div>`}
+function maps(){return `${screenHead('Map select','Unlock new worlds by winning matches. Choose your battlefield.')}<div class="map-grid">${MAPS.map(([n,d,bg,em,idx])=>{let unlocked=save.unlockedMaps.includes(idx),sel=save.selectedMap===idx;return `<article class="map-card ${sel?'selected':''}" data-map="${idx}"><div class="map-preview" style="--mapbg:${bg}"><span class="map-glyph">${em}</span></div><div class="map-card-body"><h3>${n}</h3><p>${d}</p><div class="map-foot"><span>${unlocked?'✦ UNLOCKED':`🔒 ${idx} WINS TO UNLOCK`}</span><span class="${sel?'select-label':''}">${sel?'✓ SELECTED':unlocked?'SELECT →':'LOCKED'}</span></div></div></article>`}).join('')}</div>`}
+function shop(){let items=SHOP[shopTab];return `${screenHead('The shop','Dress up your square and leave a trail worth chasing.')}<div class="tab-row">${Object.keys(SHOP).map(t=>`<button class="tab ${shopTab===t?'active':''}" data-tab="${t}">${t.toUpperCase()}</button>`).join('')}</div><div class="item-grid">${items.map(([name,icon,price])=>{let owned=(save.owned[shopTab]||[]).includes(name),equipped=save.equipped[shopTab]===name;return `<article class="panel item-card"><div class="item-visual">${icon}</div><h3>${name}</h3><p>${owned?(equipped?'Currently equipped':'Ready for your loadout'):`A little extra personality for the arena.`}</p><button class="${equipped?'equipped':''}" data-item="${name}" data-price="${price}" ${equipped?'disabled':''}>${equipped?'✓ EQUIPPED':owned?'EQUIP':`● ${price} COINS`}</button></article>`}).join('')}</div>`}

