 function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR NEXT GREAT RUN STARTS HERE</div><h1>MAKE YOUR<br><em>MARK.</em></h1><p>Color the arena. Draw a daring trail. Close the loop and turn empty space into your kingdom.</p><div class="actions"><button class="primary" data-action="quickplay">PLAY NOW <span class="arrow">↗</span></button><button class="secondary" data-page="maps">CHOOSE A MAP</button><span class="tiny-note">✦ Free to play · Offline ready</span></div></div><div class="showcase"><div class="show-grid"></div><div class="show-tag tag-a">✦ CURRENT SEASON <b>Paper Planes</b></div><div class="territory-board">${Array.from({length:63},(_,i)=>`<i class="tile" style="animation-delay:${(i%9)*-.22}s"></i>`).join('')}</div><div class="paper-player">▧</div><i class="floating-square f1"></i><i class="floating-square f2"></i><i class="floating-square f3"></i><div class="show-tag tag-b"><b>01</b>ONE TRAIL. BIG AMBITION.</div></div></section><div class="section-head"><div><h2>Pick your playstyle</h2><p>Five ways to make the arena yours.</p></div><button class="text-link" data-page="modes">ALL MODES →</button></div><section class="mode-grid">${MODES.slice(0,4).map(([id,ic,n,d,s])=>`<article class="mode-card" data-mode="${id}"><div class="mode-icon">${ic}</div><h3>${n}</h3><p>${d}</p><span class="chev">↗</span></article>`).join('')}</section><section class="bottom-grid"><article class="panel mission-card"><div class="mission-top"><h3>⚑ Daily mission</h3><span>+75 COINS</span></div><div class="mission-desc">Capture 500 tiles across your matches</div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,(save.missions.captures||0)/5)}%"></div></div><div class="mission-foot"><span>${Math.min(500,save.missions.captures||0)} / 500 tiles</span><button class="text-link" data-page="missions">VIEW MISSIONS →</button></div></article><article class="panel daily-card"><div class="mission-top"><h3>🎁 Daily drop</h3><span>READY TO CLAIM?</span></div><div class="mission-desc">A little something to keep your paper empire growing.</div><button class="small-btn secondary" data-page="rewards" style="padding:9px 13px;font-size:9px">OPEN REWARDS →</button></article></section>`}

input.newString:
function shop(){let items=SHOP[shopTab];return `${screenHead('The shop','Dress up your square and leave a trail worth chasing.')}<div class="tab-row">${Object.keys(SHOP).map(t=>`<button class="tab ${shopTab===t?'active':''}" data-tab="${t}">${t.toUpperCase()}</button>`).join('')}</div><div class="item-grid">${items.map(([name,icon,price])=>{let owned=(save.owned[shopTab]||[]).includes(name),equipped=save.equipped[shopTab]===name;return `<article class="panel item-card"><div class="item-visual">${icon}</div><h3>${name}</h3><p>${owned?(equipped?'Currently equipped':'Ready for your loadout'):`A little extra personality for the arena.`}</p><button class="${equipped?'equipped':''}" data-item="${name}" data-price="${price}" ${equipped?'disabled':''}>${equipped?'✓ EQUIPPED':owned?'EQUIP':`● ${price} COINS`}</button></article>`}).join('')}</div>`}
function profile(){let pct=save.matches?Math.round(save.best):0;return `${screenHead('Player profile','Your paper empire, all in one place.')}<section class="profile-layout"><article class="panel profile-hero"><div class="profile-avatar">${save.avatar}</div><div class="eyebrow" style="justify-content:center">LEVEL ${save.level} PAPER PILOT</div><h2 style="font:700 21px 'Space Grotesk';margin:12px 0">${save.name}</h2><label style="display:block;color:#9da1b7;font-size:10px;margin-bottom:8px">EDIT USERNAME</label><input id="nameInput" maxlength="18" value="${escapeHtml(save.name)}"><div style="font-size:10px;color:#a1a5bb;margin-top:12px">XP TO NEXT LEVEL</div><div class="progress-track" style="margin:8px auto;width:80%"><div class="progress-fill" style="width:${save.xp}%"></div></div><div style="font-size:10px;color:#c8f76a">${save.xp} / 100 XP</div><div style="margin-top:17px;color:#9da1b7;font-size:10px">FAVORITE SKIN · <b style="color:#fff">${save.skin}</b></div></article><div><div class="panel" style="padding:16px"><div class="stat-grid">${[['MATCHES',save.matches],['WINS',save.wins],['LOSSES',save.losses],['TILES CLAIMED',save.captured.toLocaleString()],['ELIMINATIONS',save.eliminations],['BEST AREA',`${pct}%`]].map(([l,v])=>`<div class="stat"><b>${v}</b><span>${l}</span></div>`).join('')}</div></div><div class="panel" style="padding:17px;margin-top:13px"><div class="mission-top"><h3>🏅 Achievements</h3><span>${save.wins} WINS</span></div><div class="achievement-row" style="margin-top:14px"><span class="badge">🟩 First Footprint</span><span class="badge">${save.captured>=100?'🏆':'🔒'} Land Grabber</span><span class="badge">${save.wins>=1?'⭐':'🔒'} First Victory</span><span class="badge">${save.wins>=5?'🔥':'🔒'} Win Streak</span></div></div></div></section>`}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function missions(){let cap=save.missions.captures||0,wins=save.missions.wins||0;return `${screenHead('Missions','Small goals. Bigger territory. Rewards land automatically.')}<div class="cards">${[['🖍️','Claim the page',`Capture 500 tiles · ${Math.min(500,cap)} / 500`,cap/5,75],['🏁','Get a win','Win 1 match · '+Math.min(1,wins)+' / 1',wins*100,100],['🧭','Explore the atlas',`Play on ${Math.min(3,save.matches)} / 3 maps`,save.matches*33,90]].map(([ic,n,d,p,r])=>`<article class="panel feature-card"><div style="font-size:23px">${ic}</div><h3>${n}</h3><p>${d}</p><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,p)}%"></div></div><div class="mission-foot"><span>REWARD</span><span class="reward">● ${r} COINS</span></div></article>`).join('')}</div>`}
function rewards(){let today=new Date().toDateString(),claimed=save.dailyDay===today;return `${screenHead('Daily rewards','A little paper fortune, every day you drop in.')}<article class="panel" style="max-width:680px;margin:auto;padding:25px"><div class="eyebrow">DAILY DROP · ${claimed?'CLAIMED TODAY':'AVAILABLE NOW'}</div><h2 style="font:700 25px 'Space Grotesk';margin:14px 0 7px">${claimed?'Come back tomorrow!':'Your streak starts here.'}</h2><p style="color:#a1a5bb;font-size:12px">Build your daily streak and earn a bigger bundle every seventh day.</p><div class="cards" style="grid-template-columns:repeat(7,1fr);gap:8px;margin:20px 0">${[50,60,75,90,110,130,250].map((n,i)=>`<div class="stat" style="text-align:center;padding:12px 4px"><span>DAY ${i+1}</span><b style="font-size:14px;color:#ffd76c;margin-top:8px">● ${n}</b></div>`).join('')}</div><button class="primary" data-action="daily" ${claimed?'disabled':''}>${claimed?'✓ CLAIMED':'CLAIM TODAY’S REWARD'} →</button></article>`}
function leaderboard(){let rows=[[save.name,save.wins,'YOU'],['PixelPanda',24,'BOT'],['NeonNoodle',19,'BOT'],['CaptainCrumb',16,'BOT'],['MintySquare',12,'BOT'],['OrbitToast',9,'BOT'],['BerryByte',7,'BOT']].sort((a,b)=>b[1]-a[1]);return `${screenHead('Leaderboard','The top paper pilots in your offline arcade.')}<article class="panel" style="max-width:720px;margin:auto;padding:8px 17px">${rows.map(([n,v,tag],i)=>`<div class="leader-row"><span class="leader-rank">${String(i+1).padStart(2,'0')}</span><span>${['🟧','🐼','🍜','🧢','🌿','🪐','🍓'][i]} &nbsp;${escapeHtml(n)} ${tag==='YOU'?'<small style="color:#c8f76a">YOU</small>':''}</span><b style="color:#c8f76a">${v} wins</b></div>`).join('')}</article>`}
function settings(){return `${screenHead('Settings','Make PAPER WORLD feel right at home.')}<article class="panel" style="max-width:680px;margin:auto;padding:8px 18px"><div class="settings-row"><span>Sound effects</span><button class="toggle ${save.sound?'on':''}" data-action="sound" aria-label="Toggle sound"></button></div><div class="settings-row"><span>Reduce motion</span><button class="toggle" data-action="motion" aria-label="Toggle motion"></button></div><div class="settings-row"><span>Controls</span><span style="color:#9fa3ba">WASD / ARROWS · SPACE TO DASH</span></div><div class="settings-row"><span>Game version</span><span style="color:#9fa3ba">ULTIMATE V3.0</span></div><div class="settings-row"><span>Save data</span><button class="small-btn secondary" style="padding:8px 12px" data-action="reset">RESET LOCAL SAVE</button></div></article>`}
function render(){navDraw();let pages={home,modes,maps,shop,profile,missions,rewards,leaderboard,settings};view.innerHTML=pages[currentPage]?.()||home();updateHeader()}

