function render(){navDraw();let pages={home,modes,maps,shop,profile,missions,rewards,leaderboard,settings,game:gameScreen};view.innerHTML=pages[currentPage]?.()||home();updateHeader()}
const CW=960,CH=600,COLS=40,ROWS=25,CELL=24;const COLORS=['#bcf36b','#ff719d','#62dce8','#ffb65c','#a885ff','#62dc9b','#f4e268','#ff6e5d','#65a5ff'];const MAPSTYLES=[['#222844','#a6b0d0'],['#15132f','#31dff5'],['#4b382d','#ffbf6a'],['#b9e8f4','#4d91b7'],['#243f35','#8fe28c'],['#141525','#aaa6ff'],['#57344e','#ffb4db'],['#46252a','#ff875b'],['#211b45','#72ddff'],['#332b20','#ffda67']];let game=null,frameId=0;
function gameScreen(){return `<div class="game-wrap"><div class="game-top"><div class="game-title"><span id="gameModeName">CLASSIC ARENA</span><small>${MAPS[save.selectedMap][0]} · ONE TRAIL. BIG AMBITION.</small></div><div class="game-stats"><div class="game-stat"><b id="timeStat">03:00</b><span>TIME</span></div><div class="game-stat"><b id="areaStat">0%</b><span>YOUR AREA</span></div><div class="game-stat"><b id="botsStat">8</b><span>RIVALS</span></div></div></div><div class="game-shell"><canvas id="gameCanvas" class="game-canvas" width="960" height="600" aria-label="Paper World territory arena"></canvas><div id="gameOverlay" class="game-overlay"><div class="overlay-card"><div class="result-emoji">▧</div><div class="eyebrow" style="justify-content:center">${MAPS[save.selectedMap][0].toUpperCase()}</div><h2>Ready, ${escapeHtml(save.name)}?</h2><p>Move with <b>WASD / arrow keys</b>. Leave your territory and loop back to claim the space. Tap <b>SPACE</b> for a paper dash!</p><button class="primary" data-action="startGame">START MATCH →</button></div></div><div class="mobile-controls"><button class="dpad" data-dir="up">↑</button><button class="dpad" data-dir="left">←</button><button class="dpad" data-dir="down">↓</button><button class="dpad" data-dir="right">→</button></div></div><div class="game-footer"><span><span class="keycap">WASD</span> MOVE &nbsp; <span class="keycap">SPACE</span> DASH <span id="dashInfo" style="color:#c8f76a">READY</span></span><button class="pause-btn" data-action="pauseGame">Ⅱ PAUSE</button></div></div>`}
function startGame(mode=selectedMode){selectedMode=mode;currentPage='game';render();const overlay=$('#gameOverlay');overlay.style.display='none';const counts={classic:8,time:8,survival:4,practice:2,hardcore:8};let n=counts[mode]||8;if(mode==='hardcore')n=8;game={mode,owner:new Int8Array(COLS*ROWS).fill(-1),trails:new Int8Array(COLS*ROWS).fill(-1),players:[],stepAcc:0,last:0,elapsed:0,ended:false,paused:false,dashUntil:0,dashReady:0,dashCooldown:0,captured:0,aliveBots:n};let points=[[5,12],[32,5],[34,19],[7,20],[19,4],[19,20],[5,4],[34,12],[21,12]];for(let i=0;i<=n;i++){let p=points[i],id=i;game.players.push({id,x:p[0],y:p[1],dir:[[1,0],[0,1],[-1,0],[0,-1]][i%4],trail:[],alive:true,turn:0,home:p,ai:i>0,skill:mode==='hardcore'?2:mode==='practice'?0:1,score:0,respawn:0})}for(let p of game.players)for(let y=p.y-1;y<=p.y+1;y++)for(let x=p.x-1;x<=p.x+1;x++)claim(p.id,x,y);$('#gameModeName').textContent=MODES.find(a=>a[0]===mode)[2].toUpperCase()+' ARENA';$('#botsStat').textContent=n;game.last=performance.now();gameTick(game.last);}
function ix(x,y){return y*COLS+x}function inside(x,y){return x>=0&&y>=0&&x<COLS&&y<ROWS}function claim(id,x,y){if(inside(x,y))game.owner[ix(x,y)]=id}
function dirFor(d){return {up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[d]}
function changeDir(d){if(!game||game.ended||game.paused)return;let v=dirFor(d);if(!v)return;let p=game.players[0];if(v[0]===-p.dir[0]&&v[1]===-p.dir[1])return;p.dir=v}
function dash(){if(!game||game.ended||game.paused||performance.now()<game.dashCooldown)return;game.dashUntil=performance.now()+850;game.dashCooldown=performance.now()+5200;toast('PAPER DASH!');}
function aiChoose(p){let dirs=[[1,0],[0,1],[-1,0],[0,-1]].filter(d=>!(d[0]===-p.dir[0]&&d[1]===-p.dir[1]));let open=p.trail.length>0;let options=dirs.filter(d=>{let x=p.x+d[0],y=p.y+d[1];return inside(x,y)&&game.trails[ix(x,y)]!==p.id});if(!options.length)return;p.turn++;if(open&&p.trail.length>=(p.skill===2?10:15)){let own=options.filter(d=>game.owner[ix(p.x+d[0],p.y+d[1])]===p.id);if(own.length){p.dir=own.sort((a,b)=>dist(p.x+a[0],p.y+a[1],p.home[0],p.home[1])-dist(p.x+b[0],p.y+b[1],p.home[0],p.home[1]))[0];return}}if(!open){let enemy=options.find(d=>game.owner[ix(p.x+d[0],p.y+d[1])]!==p.id);if(enemy&&p.turn%5===0){p.dir=enemy;return}}let shouldTurn=p.turn%(p.skill===2?3:5)===0||Math.random()<(p.skill===2?.1:.18);if(shouldTurn)p.dir=options[Math.floor(Math.random()*options.length)]}
function dist(x,y,a,b){return Math.abs(x-a)+Math.abs(y-b)}
function doStep(p){if(!p.alive)return;let [dx,dy]=p.dir,nx=p.x+dx,ny=p.y+dy;if(!inside(nx,ny)){die(p);return}let k=ix(nx,ny),trailOwner=game.trails[k];if(trailOwner>=0&&trailOwner!==p.id){let target=game.players[trailOwner];if(target)die(target);game.trails[k]=-1}if(trailOwner===p.id){die(p);return}p.x=nx;p.y=ny;if(p.ai)aiChoose(p);if(game.owner[k]!==p.id){game.trails[k]=p.id;p.trail.push(k);if(p.trail.length>160){die(p);return}}else if(p.trail.length){closeLoop(p)}if(game.trails[k]>=0&&game.trails[k]!==p.id){let victim=game.players[game.trails[k]];if(victim)die(victim);game.trails[k]=-1}}
function closeLoop(p){let id=p.id;for(let k of p.trail){game.owner[k]=id;game.trails[k]=-1}let seen=new Uint8Array(COLS*ROWS),q=[];const add=(x,y)=>{if(!inside(x,y))return;let k=ix(x,y);if(seen[k]||game.owner[k]===id)return;seen[k]=1;q.push(k)};for(let x=0;x<COLS;x++){add(x,0);add(x,ROWS-1)}for(let y=0;y<ROWS;y++){add(0,y);add(COLS-1,y)}for(let i=0;i<q.length;i++){let k=q[i],x=k%COLS,y=(k/COLS)|0;add(x+1,y);add(x-1,y);add(x,y+1);add(x,y-1)}let gained=0;for(let k=0;k<game.owner.length;k++)if(!seen[k]&&game.owner[k]!==id){game.owner[k]=id;gained++}game.captured+=gained+p.trail.length;p.score+=gained;p.trail=[];if(id===0){save.captured+=gained;save.missions.captures=(save.missions.captures||0)+gained;persist()} }
function die(p){if(!p.alive)return;for(let k of p.trail)game.trails[k]=-1;p.trail=[];p.alive=false;if(p.id===0){game.players[0].respawn=performance.now()+950;game.dashUntil=0;toast('Trail snapped! Rebuilding your square…')}else{game.aliveBots=Math.max(0,game.aliveBots-1);if(Math.random()<.42)save.coins+=5}setTimeout(()=>{if(!game||game.ended)return;if(p.id===0){p.x=p.home[0];p.y=p.home[1];p.alive=true;for(let y=p.y-1;y<=p.y+1;y++)for(let x=p.x-1;x<=p.x+1;x++)claim(0,x,y)}else if(game.mode==='survival'||game.mode==='classic'||game.mode==='time'||game.mode==='hardcore'){let h=p.home;p.x=h[0];p.y=h[1];p.alive=true;for(let y=h[1]-1;y<=h[1]+1;y++)for(let x=h[0]-1;x<=h[0]+1;x++)claim(p.id,x,y);game.aliveBots++}},900)}

