function die(p){if(!p.alive)return;for(let k of p.trail)game.trails[k]=-1;p.trail=[];p.alive=false;if(p.id===0){game.lives--;game.dashUntil=0;toast(game.mode==='survival'?`Trail snapped! ${Math.max(0,game.lives)} lives left.`:'Trail snapped! Rebuilding your square…');if(game.mode==='survival'&&game.lives<=0){finishGame(false);return}}else{game.aliveBots=Math.max(0,game.aliveBots-1);save.eliminations++;if(Math.random()<.42)save.coins+=5}setTimeout(()=>{if(!game||game.ended)return;if(p.id===0){p.x=p.home[0];p.y=p.home[1];p.alive=true;for(let y=p.y-1;y<=p.y+1;y++)for(let x=p.x-1;x<=p.x+1;x++)claim(0,x,y)}else{let h=p.home;p.x=h[0];p.y=h[1];p.alive=true;for(let y=h[1]-1;y<=h[1]+1;y++)for(let x=h[0]-1;x<=h[0]+1;x++)claim(p.id,x,y);game.aliveBots++}},900)}
function percent(id){let n=0;for(let x of game.owner)if(x===id)n++;return Math.round(n*100/game.owner.length)}
function gameTick(now){if(!game||currentPage!=='game')return;let dt=Math.min(80,now-game.last);game.last=now;if(!game.paused&&!game.ended){game.elapsed+=dt;let pace=game.mode==='hardcore'?95:game.mode==='practice'?145:game.mode==='survival'?Math.max(72,140-Math.floor(game.elapsed/30000)*9):120;if(game.dashUntil>now)pace*=.55;game.stepAcc+=dt;while(game.stepAcc>pace){game.stepAcc-=pace;for(let p of game.players)if(p.ai&&p.alive){if(game.mode==='survival')p.skill=Math.min(2,Math.floor(game.elapsed/45000));doStep(p)}let user=game.players[0];if(user.alive)doStep(user)}if(game.mode==='survival'&&game.elapsed>=300000)finishGame(true);else if(game.mode!=='survival'&&(game.elapsed>=180000||percent(0)>=42))finishGame(percent(0)>=42);if(game.mode==='classic'&&game.aliveBots===0)finishGame(true)}drawGame();updateGameHud(now);frameId=requestAnimationFrame(gameTick)}
function finishGame(won){if(!game||game.ended)return;game.ended=true;cancelAnimationFrame(frameId);let area=percent(0);save.matches++;save.best=Math.max(save.best,area);let score=Math.floor(game.captured+area*4);if(game.mode==='time')save.highscore=Math.max(save.highscore,score);let victory=won||area>=42;if(victory){save.wins++;save.missions.wins=(save.missions.wins||0)+1;save.coins+=100;save.xp+=45;toast('Victory! +100 coins · +45 XP')}else{save.losses++;save.coins+=25;save.xp+=15}while(save.xp>=100){save.xp-=100;save.level++;save.coins+=75}save.unlockedMaps=[...new Set([...save.unlockedMaps,...MAPS.filter((_,i)=>i<=save.wins).map((_,i)=>i)])];persist();let ov=$('#gameOverlay');ov.style.display='grid';ov.innerHTML=`<div class="overlay-card"><div class="result-emoji">${victory?'🏆':'🧻'}</div><div class="eyebrow" style="justify-content:center">MATCH COMPLETE · ${MAPS[save.selectedMap][0].toUpperCase()}</div><h2>${victory?'Board conquered!':'Nice run!'}</h2><p>You claimed <b>${area}%</b> of the arena and earned <b>${victory?100:25} coins</b>${game.mode==='time'?`<br>Run score: ${score} · Best: ${save.highscore}`:''}</p><div class="actions" style="justify-content:center"><button class="primary" data-action="replay">PLAY AGAIN</button><button class="secondary" data-action="home">MAIN MENU</button></div></div>`}
function drawGame(){let c=$('#gameCanvas');if(!c||!game)return;let ctx=c.getContext('2d'),[bg,grid]=MAPSTYLES[save.selectedMap];ctx.clearRect(0,0,CW,CH);ctx.fillStyle=bg;ctx.fillRect(0,0,CW,CH);if(save.selectedMap===5){for(let i=0;i<55;i++){let x=(i*173+43)%CW,y=(i*89+17)%CH;ctx.fillStyle='#ffffff88';ctx.fillRect(x,y,1.5,1.5)}}if(save.selectedMap===7){for(let i=0;i<8;i++){ctx.fillStyle=i%2?'#ff8b4930':'#ffce5830';ctx.beginPath();ctx.arc((i*177+80)%CW,(i*113+40)%CH,18+i%4*6,0,Math.PI*2);ctx.fill()}}ctx.fillStyle='#ffffff0a';ctx.fillRect(0,0,CW,CH);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){let k=ix(x,y),own=game.owner[k];if(own>=0){ctx.fillStyle=COLORS[own%COLORS.length];ctx.globalAlpha=.48;ctx.fillRect(x*CELL+1,y*CELL+1,CELL-2,CELL-2);ctx.globalAlpha=1}let tid=game.trails[k];if(tid>=0){ctx.fillStyle=COLORS[tid%COLORS.length];ctx.shadowColor=COLORS[tid%COLORS.length];ctx.shadowBlur=10;ctx.fillRect(x*CELL+4,y*CELL+4,CELL-8,CELL-8);ctx.shadowBlur=0}}ctx.strokeStyle=grid+'28';ctx.lineWidth=1;for(let x=0;x<=COLS;x++){ctx.beginPath();ctx.moveTo(x*CELL,0);ctx.lineTo(x*CELL,CH);ctx.stroke()}for(let y=0;y<=ROWS;y++){ctx.beginPath();ctx.moveTo(0,y*CELL);ctx.lineTo(CW,y*CELL);ctx.stroke()}for(const p of game.players){if(!p.alive)continue;let x=p.x*CELL+CELL/2,y=p.y*CELL+CELL/2,color=COLORS[p.id%COLORS.length];ctx.save();ctx.translate(x,y);ctx.shadowColor=color;ctx.shadowBlur=p.id===0?18:9;ctx.fillStyle=color;let size=p.id===0?17:14;ctx.beginPath();ctx.roundRect(-size/2,-size/2,size,size,4);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#172033';ctx.beginPath();ctx.arc(-3,-1,1.5,0,Math.PI*2);ctx.arc(3,-1,1.5,0,Math.PI*2);ctx.fill();ctx.restore();if(p.id!==0){ctx.fillStyle='#ffffff99';ctx.font='9px DM Sans';ctx.textAlign='center';ctx.fillText(['Mochi','Zippy','Pip','Dot','Nova','Boba','Kiki','Byte'][p.id-1],x,y-12)}}ctx.strokeStyle='#ffffff66';ctx.lineWidth=2;ctx.strokeRect(1,1,CW-2,CH-2)}
function updateGameHud(now){if(!game)return;let left=Math.max(0,180-Math.floor(game.elapsed/1000)),time=game.mode==='survival'?`${Math.floor(game.elapsed/60000)}:${String(Math.floor(game.elapsed/1000)%60).padStart(2,'0')}`:`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;$('#timeStat').textContent=time;$('#areaStat').textContent=percent(0)+'%';$('#botsStat').textContent=game.aliveBots;$('#dashInfo').textContent=now<game.dashCooldown?`${Math.ceil((game.dashCooldown-now)/1000)}s`:'READY'}

