=today){toast('You already claimed today’s reward.');return}let yesterday=new Date(Date.now()-86400000).toDateString();save.dailyStreak=save.dailyDay===yesterday?(save.dailyStreak||0)+1:1;save.dailyDay=today;let reward=save.dailyStreak%7===0?250:50+Math.min(save.dailyStreak-1,5)*15;save.coins+=reward;persist();toast(`Daily drop claimed! +${reward} coins`);render()}if(act==='sound'){save.sound=!save.sound;persist();render()}if(act==='motion'){e.target.classList.toggle('on')}if(act==='reset'){if(confirm('Reset all local Paper World progress? This cannot be undone.')){localStorage.removeItem('paperWorldSave');save={...DEFAULT,owned:{...DEFAULT.owned},equipped:{...DEFAULT.equipped}};persist();toast('Local save reset.');render()}}});
